renderer.fragment:
void main(){
  vec2 p = (uv - 0.5) * vec2(iResolution.x / max(iResolution.y, 1.0), 1.0) * 2.0;
  float wave = sin(iTime * 3.14159);
  float r = max(u_radius * (1.0 + u_pulse * 0.12 * wave), 0.001);
  float soft = clamp(u_softness, 0.0, 1.0);
  float d = length(p);
  float inner = r * (1.0 - soft);
  float core = 1.0 - smoothstep(inner, r + 0.003, d);
  float halo = exp(-max(d - inner, 0.0) / (0.02 + soft * 0.35 * r + soft * 0.08)) * soft;
  float glow = clamp(core + halo * 0.7 * (1.0 - core), 0.0, 1.0);
  glow *= 1.0 + u_pulse * 0.15 * wave;
  float a = clamp(glow, 0.0, 1.0);
  vec3 hot = mix(u_color, vec3(1.0), 0.45 * (1.0 - smoothstep(0.0, r * 0.7, d)));
  fragColor = vec4(hot * a, a);
}
